using namespace std;

int main() {
    string s((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    vector<char> ops;        // pending operators: '+' for add, '-' for sub
    vector<long long> vals;  // evaluated arguments
    for (size_t i = 0; i < s.size();) {
        char c = s[i];
        if (c == 'a' || c == 's') { ops.push_back(c == 'a' ? '+' : '-'); i += 3; }
        else if (c == ')') {
            // Both arguments of the innermost open call are on top of the value stack.
            long long right = vals.back(); vals.pop_back();
            long long left = vals.back(); vals.pop_back();
            vals.push_back(ops.back() == '+' ? left + right : left - right);
            ops.pop_back();
            i++;
        } else if (c == '-' || isdigit((unsigned char)c)) {
            bool neg = c == '-';
            if (neg) i++;
            long long v = 0;
            while (i < s.size() && isdigit((unsigned char)s[i])) v = v * 10 + (s[i++] - '0');
            vals.push_back(neg ? -v : v);
        } else i++;  // '(', ',', whitespace
    }
    printf("%lld\n", vals[0]);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] s = System.in.readAllBytes();
        int n = s.length;
        char[] ops = new char[n + 1]; // pending operators: '+' for add, '-' for sub
        long[] vals = new long[n + 1]; // evaluated arguments
        int no = 0, nv = 0;
        for (int i = 0; i < n;) {
            byte c = s[i];
            if (c == 'a' || c == 's') { ops[no++] = c == 'a' ? '+' : '-'; i += 3; }
            else if (c == ')') {
                // Both arguments of the innermost open call are on top of the value stack.
                long right = vals[--nv], left = vals[--nv];
                vals[nv++] = ops[--no] == '+' ? left + right : left - right;
                i++;
            } else if (c == '-' || (c >= '0' && c <= '9')) {
                boolean neg = c == '-';
                if (neg) i++;
                long v = 0;
                while (i < n && s[i] >= '0' && s[i] <= '9') v = v * 10 + (s[i++] - '0');
                vals[nv++] = neg ? -v : v;
            } else i++; // '(', ',', whitespace
        }
        System.out.println(vals[0]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

func main() {
	s, _ := io.ReadAll(os.Stdin)
	var ops []byte   // pending operators: '+' for add, '-' for sub
	var vals []int64 // evaluated arguments
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == 'a' || c == 's':
			if c == 'a' {
				ops = append(ops, '+')
			} else {
				ops = append(ops, '-')
			}
			i += 3
		case c == ')':
			// Both arguments of the innermost open call are on top of the value stack.
			right, left := vals[len(vals)-1], vals[len(vals)-2]
			vals = vals[:len(vals)-2]
			op := ops[len(ops)-1]
			ops = ops[:len(ops)-1]
			if op == '+' {
				vals = append(vals, left+right)
			} else {
				vals = append(vals, left-right)
			}
			i++
		case c == '-' || (c >= '0' && c <= '9'):
			neg := c == '-'
			if neg {
				i++
			}
			var v int64
			for i < len(s) && s[i] >= '0' && s[i] <= '9' {
				v = v*10 + int64(s[i]-'0')
				i++
			}
			if neg {
				v = -v
			}
			vals = append(vals, v)
		default: // '(', ',', whitespace
			i++
		}
	}
	fmt.Println(vals[0])
}
